import ctypes
import numpy as np

class GSLMatrix:
    def __init__(self, data, rows, cols):
        self.matrix = ctypes.c_void_p()
        self.rows = rows
        self.cols = cols
        self.data = data

    def __del__(self):
        if self.matrix:
            gsl.gsl_matrix_free(ctypes.byref(self.matrix))

    @property
def data(self):
    return self._data

    @data.setter
def data(self, value):
    self._data = value
    self._fill_matrix()

    def _fill_matrix(self):
        if self.matrix:
            gsl.gsl_matrix_free(ctypes.byref(self.matrix))
        self.matrix = gsl.gsl_matrix_alloc(self.rows, self.cols)
        for i in range(self.rows):
            for j in range(self.cols):
                gsl.gsl_matrix_set(ctypes.byref(self.matrix), i, j, self._data[i][j])

    def to_numpy(self):
        result = np.zeros((self.rows, self.cols))
        for i in range(self.rows):
            for j in range(self.cols):
                result[i][j] = gsl.gsl_matrix_get(ctypes.byref(self.matrix), i, j)
        return result

    def _fill_from_array(self, arr):
        if self.rows != len(arr) or self.cols != len(arr[0]):
            raise ValueError("Matrix dimensions do not match")
        for i in range(self.rows):
            for j in range(self.cols):
                gsl.gsl_matrix_set(ctypes.byref(self.matrix), i, j, arr[i][j])

    @staticmethod
def numpy_to_gsl_matrix(np_array):
    if not isinstance(np_array, np.ndarray):
        raise TypeError("Input must be a numpy array")
    if np_array.ndim != 2:
        raise ValueError("Input must be a 2D array")
    matrix = GSLMatrix(np.zeros((np_array.shape[0], np_array.shape[1])), np_array.shape[0], np_array.shape[1])
    matrix._fill_from_array(np_array)
    return matrix

    @staticmethod
def gsl_matrix_to_numpy(matrix):
    if not isinstance(matrix, GSLMatrix):
        raise TypeError("Input must be a GSLMatrix object")
    return matrix.to_numpy()

    @staticmethod
def gsl_multifit_covar(jacobian, epsrel):
    if not isinstance(jacobian, GSLMatrix):
        raise TypeError("Jacobian must be a GSLMatrix object")
    if not isinstance(epsrel, float):
        raise TypeError("Epsilon relative must be a float")
    if jacobian.rows != jacobian.cols:
        raise ValueError("Jacobian matrix must be square")
    covar = GSLMatrix(np.zeros((jacobian.rows, jacobian.cols)), jacobian.rows, jacobian.cols)
    gsl.gsl_multifit_covar(ctypes.byref(jacobian.matrix), ctypes.c_double(epsrel), ctypes.byref(covar.matrix))
    return covar

