class gsl_multifit_fdfsolver(ctypes.Structure):
    _fields_ = [
        ("solver", ctypes.POINTER(ctypes.c_void_p))
    ]

# Function to create a solver
def gsl_multifit_fdfsolver_create(n, p):
    solver = gsl_multifit_fdfsolver()
    solver.solver = ctypes.c_void_p()
    gsl.gsl_multifit_fdfsolver_create.argtypes = [ctypes.c_int, ctypes.c_int]
    gsl.gsl_multifit_fdfsolver_create.restype = ctypes.POINTER(gsl_multifit_fdfsolver)
    return gsl.gsl_multifit_fdfsolver_create(n, p)

# Function to set the function for the solver
def gsl_multifit_fdfsolver_set(solver, function):
    gsl.gsl_multifit_fdfsolver_set.argtypes = [ctypes.POINTER(gsl_multifit_fdfsolver), ctypes.POINTER(gsl_multifit_function_fdf)]
    gsl.gsl_multifit_fdfsolver_set.restype = ctypes.c_int
    return gsl.gsl_multifit_fdfsolver_set(solver, function)

# Function to perform one iteration of the solver
def gsl_multifit_fdfsolver_iterate(solver):
    gsl.gsl_multifit_fdfsolver_iterate.argtypes = [ctypes.POINTER(gsl_multifit_fdfsolver)]
    gsl.gsl_multifit_fdfsolver_iterate.restype = ctypes.c_int
    return gsl.gsl_multifit_fdfsolver_iterate(solver)

# Function to get the parameters of the solver
def gsl_multifit_fdfsolver_get(solver, x):
    gsl.gsl_multifit_fdfsolver_get.argtypes = [ctypes.POINTER(gsl_multifit_fdfsolver), ctypes.POINTER(ctypes.c_double)]
    gsl.gsl_multifit_fdfsolver_get.restype = ctypes.c_int
    return gsl.gsl_multifit_fdfsolver_get(solver, x)

