def main():
    # Input: dictionary with n, p, and initial x
    input_data = {
        "n": 2,
        "p": 1,
        "x": [1.0, 2.0]
    }

    # Create a function for the solver
    def func(x, params):
        return np.array([x[0] + x[1], x[0] - x[1]])

    def df(x, params):
        return np.array([[1.0, 1.0], [1.0, -1.0]])

    def f(x, params):
        return np.array([x[0] + x[1] - 3.0, x[0] - x[1] - 1.0])

    function = gsl_multifit_function_fdf()
    function.function = ctypes.pointer(ctypes.c_double(func))
