import numpy as np

class GSLFunction:
    def __init__(self, f):
        self.f = f

    def __call__(self, x, params):
        return self.f(x)

libgslcblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

def gsl_integration_qcheb(f, a, b, cheb12, cheb24):
    f_func = GSLFunction(f)
    f_c = ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double, ctypes.c_void_p)(f_func)

    gsl.gsl_integration_qcheb.argtypes = [ctypes.POINTER(ctypes.c_double), ctypes.c_double, ctypes.c_double, ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_double)]
    gsl.gsl_integration_qcheb.restype = ctypes.c_int

    cheb12_arr = (ctypes.c_double * 13)() 
    cheb24_arr = (ctypes.c_double * 25)() 

    gsl.gsl_integration_qcheb(ctypes.byref(f_c), a, b, cheb12_arr, cheb24_arr)

    return np.array(cheb12_arr, dtype=np.float64), np.array(cheb24_arr, dtype=np.float64)

