import ctypes
import os

class gsl_rng_type(ctypes.Structure):
    pass

class gsl_rng(ctypes.Structure):
    pass

def allocate_rng(rng_name):
    # Load required libraries
    try:
        ctypes.CDLL(os.path.join('/usr/local/gsl/lib', 'libgslcblas.so'), mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL(os.path.join('/usr/local/gsl/lib', 'libgsl.so'))
    except Exception as e:
        raise RuntimeError(f"Failed to load GSL library: {e}")

    # Define function signature
    gsl_rng_alloc = gsl.gsl_rng_alloc
    gsl_rng_alloc.argtypes = [ctypes.c_char_p]
    gsl_rng_alloc.restype = ctypes.POINTER(gsl_rng)

    # Allocate RNG
    try:
        rng_ptr = gsl_rng_alloc(ctypes.c_char_p(rng_name.encode('utf-8')))
        if not rng_ptr:
            raise RuntimeError("Failed to allocate RNG")
        return rng_ptr
    except Exception as e:
        gsl.gsl_rng_free(rng_ptr)
        raise RuntimeError(f"Failed to allocate RNG: {e}")

# Test cases
