    try:
        rng1 = allocate_rng('mt19937')
        print("Allocated mt19937 RNG pointer:", rng1)
        rng2 = allocate_rng('lagged_fibonacci')
        print("Allocated lagged_fibonacci RNG pointer:", rng2)
    except Exception as e:
        print(f"Error: {e}")

