import ctypes

class GSLVector:
    _lib = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

    _lib.gsl_vector_alloc.argtypes = [ctypes.c_size_t]
    _lib.gsl_vector_alloc.restype = ctypes.POINTER(ctypes.c_double)

    _lib.gsl_vector_set.argtypes = [ctypes.POINTER(ctypes.c_double), ctypes.c_size_t, ctypes.c_double]
    _lib.gsl_vector_set.restype = None

    _lib.gsl_vector_get.argtypes = [ctypes.POINTER(ctypes.c_double), ctypes.c_size_t]
    _lib.gsl_vector_get.restype = ctypes.c_double

    _lib.gsl_vector_free.argtypes = [ctypes.POINTER(ctypes.c_double)]
    _lib.gsl_vector_free.restype = None

    def __init__(self, size):
        self.vector = self._lib.gsl_vector_alloc(size)

    def set_value(self, index, value):
        self._lib.gsl_vector_set(self.vector, index, value)

    def get_value(self, index):
        return self._lib.gsl_vector_get(self.vector, index)

    def free(self):
        self._lib.gsl_vector_free(self.vector)


def create_and_manipulate_vector(values):
    vec = GSLVector(len(values))
    for i, v in enumerate(values):
        vec.set_value(i, v)
    result = []
    for i in range(len(values)):
        result.append(vec.get_value(i))
    vec.free()
    return result

