import ctypes
import numpy as np

class GSLMatrix:
    def __init__(self, data):
        self.data = data
        self.size = len(data)

    def to_gsl(self):
        gsl_matrix = ctypes.create_string_buffer(ctypes.c_size_t(self.size * self.size).value * ctypes.sizeof(ctypes.c_double))
        ptr = ctypes.pointer(gsl_matrix)
        for i in range(self.size):
            for j in range(self.size):
                val = self.data[i][j]
                ctypes.memmove(ctypes.addressof(ptr.contents) + i * self.size + j, ctypes.c_double(val).pointer, ctypes.sizeof(ctypes.c_double))
        return gsl_matrix

    def from_gsl(self, gsl_matrix):
        self.data = [[0.0 for _ in range(self.size)] for _ in range(self.size)]
        for i in range(self.size):
            for j in range(self.size):
                val = ctypes.c_double(0.0)
                ctypes.memmove(ctypes.addressof(val), ctypes.addressof(gsl_matrix.contents) + i * self.size + j, ctypes.sizeof(ctypes.c_double))
                self.data[i][j] = val.value

    def __str__(self):
        return '\n'.join([' '.join(map(str, row)) for row in self.data])

def matrix_to_gsl(matrix):
    return GSLMatrix(matrix).to_gsl()

def gsl_matrix_to_numpy(gsl_matrix):
    size = ctypes.c_size_t(gsl_matrix.size).value
    matrix = [[0.0 for _ in range(size)] for _ in range(size)]
    for i in range(size):
        for j in range(size):
            val = ctypes.c_double(0.0)
            ctypes.memmove(ctypes.addressof(val), ctypes.addressof(gsl_matrix.contents) + i * size + j, ctypes.sizeof(ctypes.c_double))
            matrix[i][j] = val.value
    return matrix

