gsl.gsl_linalg_exponential_ss.argtypes = [ctypes.POINTER(ctypes.c_double), ctypes.c_int, ctypes.POINTER(ctypes.c_double)]

def compute_matrix_exponential(matrix, mode):
    if not isinstance(matrix, list):
        raise ValueError("Input matrix must be a list of lists.")
    size = len(matrix)
    if any(len(row) != size for row in matrix):
        raise ValueError("All rows in the matrix must have the same length.")

    gsl_matrix = matrix_to_gsl(matrix)

    result = (ctypes.c_double * (size * size))()
    gsl.gsl_linalg_exponential_ss(gsl_matrix, mode, result)

    return gsl_matrix_to_numpy(result)

