import ctypes

class GSLMatrix:
    _lib = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    _lib = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

    _create_gsl_matrix = _lib.gsl_matrix_alloc
    _create_gsl_matrix.argtypes = [ctypes.c_int, ctypes.c_int]
    _create_gsl_matrix.restype = ctypes.POINTER(ctypes.c_double)

    _retrieve_gsl_matrix = _lib.gsl_matrix_get
    _retrieve_gsl_matrix.argtypes = [ctypes.POINTER(ctypes.c_double), ctypes.c_size_t, ctypes.c_size_t]
    _retrieve_gsl_matrix.restype = ctypes.c_double

    _free_gsl_matrix = _lib.gsl_matrix_free
    _free_gsl_matrix.argtypes = [ctypes.POINTER(ctypes.c_double)]

    def __init__(self, rows, cols):
        self.rows = rows
        self.cols = cols
        self.matrix = self._create_gsl_matrix(rows, cols)

    def set_elements(self, data):
        for i in range(self.rows):
            for j in range(self.cols):
                self._set_element(i, j, data[i][j])

    def _set_element(self, row, col, value):
        self._lib.gsl_matrix_set(self.matrix, row, col, value)

    def get_element(self, row, col):
        return self._retrieve_gsl_matrix(self.matrix, row, col)

    def free(self):
        self._free_gsl_matrix(self.matrix)

def create_gsl_matrix(data):
    rows = len(data)
    cols = len(data[0])
    matrix = GSLMatrix(rows, cols)
    matrix.set_elements(data)
    return matrix

def retrieve_gsl_matrix(gsl_matrix):
    rows = gsl_matrix.rows
    cols = gsl_matrix.cols
    result = [[0.0 for _ in range(cols)] for _ in range(rows)]
    for i in range(rows):
        for j in range(cols):
            result[i][j] = gsl_matrix.get_element(i, j)
    return result

def free_gsl_matrix(gsl_matrix):
    gsl_matrix.free()

