    _retrieve_gsl_matrix = _lib2.gsl_matrix_get
    _retrieve_gsl_matrix.argtypes = [ctypes.POINTER(ctypes.c_double), ctypes.c_int, ctypes.c_int]
    _retrieve_gsl_matrix.restype = ctypes.c_double

    _free_gsl_matrix = _lib.gsl_matrix_free
    _free_gsl_matrix.argtypes = [ctypes.POINTER(ctypes.c_double)]

    @staticmethod
    def create_gsl_matrix(data):
        rows = len(data)
        cols = len(data[0])
        matrix = GSLMatrix._create_gsl_matrix(rows, cols)
        for i in range(rows):
            for j in range(cols):
                GSLMatrix._lib.gsl_matrix_set(matrix, i, j, data[i][j])
        return matrix

    @staticmethod
    def retrieve_gsl_matrix(gsl_matrix):
        rows = gsl_matrix.shape[0]
        cols = gsl_matrix.shape[1]
        matrix = [[0.0 for _ in range(cols)] for _ in range(rows)]
        for i in range(rows):
            for j in range(cols):
                matrix[i][j] = GSLMatrix._retrieve_gsl_matrix(gsl_matrix, i, j)
        return matrix

    @staticmethod
    def free_gsl_matrix(gsl_matrix):
        GSLMatrix._free_gsl_matrix(gsl_matrix)

