# Load GSL libraries
gsl_cblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

# Define function signatures
gsl.gsl_cdf_cauchy_Pinv.argtypes = [ctypes.c_double, ctypes.c_double]
gsl.gsl_cdf_cauchy_Pinv.restype = ctypes.c_double
gsl.gsl_cdf_cauchy_Qinv.argtypes = [ctypes.c_double, ctypes.c_double]
gsl.gsl_cdf_cauchy_Qinv.restype = ctypes.c_double

def cauchy_inverse_cdf(prob, scale):
    if prob < 0 or prob > 1:
        raise ValueError("Probability must be between 0 and 1")
    if scale <= 0:
        raise ValueError("Scale parameter must be positive")

    if prob >= 0 and prob <= 1:
        return gsl.gsl_cdf_cauchy_Pinv(prob, scale)
    else:
        return gsl.gsl_cdf_cauchy_Qinv(prob, scale)

# Test cases
