    (0.5, 1.0),  # Should return 0.0
    (0.75, 1.0),  # Should return approximately 0.6745
    (0.25, 1.0),  # Should return approximately -0.6745
    (0.95, 1.0),  # Should return approximately 1.6449
    (0.05, 1.0),  # Should return approximately -1.6449
]

results = []
for p, a in test_cases:
    try:
        result = cauchy_inverse_cdf(p, a)
        results.append((p, a, result))
    except Exception as e:
        results.append((p, a, str(e)))

return results

import ctypes
import sys

# Load GSL libraries
gsl_cblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

# Define function prototypes
gsl.cdf_cauchy_Pinv.argtypes = [ctypes.c_double, ctypes.c_double]
gsl.cdf_cauchy_Pinv.restype = ctypes.c_double
gsl.cdf_cauchy_Qinv.argtypes = [ctypes.c_double, ctypes.c_double]
gsl.cdf_cauchy_Qinv.restype = ctypes.c_double

def cauchy_inverse_cdf(prob, scale):
    if prob < 0 or prob > 1:
        raise ValueError("Probability must be between 0 and 1.")
    if scale <= 0:
        raise ValueError("Scale parameter must be positive.")

    if prob >= 0.5:
        return gsl.cdf_cauchy_Qinv(prob, scale)
    else:
        return gsl.cdf_cauchy_Pinv(prob, scale)

# Test cases
test_cases = [
    (0.5, 1.0, 0.0),  # P=0.5, a=1.0, expected 0.0
    (0.75, 1.0, 0.6433),  # P=0.75, a=1.0, expected ~0.6433
    (0.25, 1.0, -0.6433),  # Q=0.25, a=1.0, expected ~-0.6433
    (0.9, 2.0, 1.4142),  # P=0.9, a=2.0, expected ~1.4142
    (0.1, 2.0, -1.4142)   # Q=0.1, a=2.0, expected ~-1.4142
]

for p, a, expected in test_cases:
    result = cauchy_inverse_cdf(p, a)
    print(f"Test case: P={p}, a={a}, Result={result}, Expected={expected}, Difference={abs(result - expected)}")

if __name__ == "__main__":
    import sys
    if len(sys.argv) != 3:
        print("Usage: python cauchy_inverse_cdf.py <probability> <scale>")
        sys.exit(1)
    try:
